// Application State
let appState = {
  dataset: 'startups', // 'startups' or 'who_life_expectancy'
  method: 'Linear Regression',
  k: 2,
  mode: 'stepwise', // 'stepwise' or 'exhaustive'
  
  // Startups simulator inputs
  startups: {
    rdSpend: 80000,
    adminSpend: 120000,
    mktSpend: 250000,
    state: 'New York'
  },
  
  // WHO Life Expectancy simulator inputs
  who: {
    'Schooling': 12,
    'Adult Mortality': 150,
    'Polio': 85,
    'BMI': 40,
    'GDP': 6000,
    'Alcohol': 4.5,
    'Hepatitis B': 80,
    'Total expenditure': 6.0
  }
};

// Chart instances
let rmseChart = null;
let r2Chart = null;

// Initialize on DOM ready
document.addEventListener('DOMContentLoaded', () => {
  initGlobalControls();
  initCharts();
  renderDatasetChange();
});

function initGlobalControls() {
  // Dataset Dropdown Switcher
  const datasetSelect = document.getElementById('datasetSelect');
  datasetSelect.addEventListener('change', (e) => {
    appState.dataset = e.target.value;
    appState.k = (appState.dataset === 'startups') ? 2 : 4;
    renderDatasetChange();
  });

  // Method Dropdown
  const methodSelect = document.getElementById('methodSelect');
  methodSelect.addEventListener('change', (e) => {
    appState.method = e.target.value;
    renderModelUpdate();
  });

  // Strategy Mode Buttons
  const modeButtons = document.querySelectorAll('#modeControlGroup .seg-mini-btn');
  modeButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      modeButtons.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      appState.mode = btn.dataset.mode;
      renderModelUpdate();
    });
  });

  // Table Search Filter
  const searchInput = document.getElementById('tableSearchInput');
  searchInput.addEventListener('input', (e) => {
    filterRawDataTable(e.target.value.toLowerCase());
  });
}

function renderDatasetChange() {
  const isStartups = (appState.dataset === 'startups');

  // 1. Update Hero Text & Stats
  if (isStartups) {
    document.getElementById('heroBadgeTag').textContent = 'AI & Machine Learning Lab • L07';
    document.getElementById('heroTitlePrefix').textContent = '50 Startups';
    document.getElementById('heroTitleSuffix').textContent = 'Regression Explorer';
    document.getElementById('heroSubtitle').textContent = '以完整 Scikit-learn 模型評估方案，探索 1~5 個特徵對於新創公司獲利的影響，比較最佳模型、檢視 RMSE / R²，並即時預測新創獲利。';
    document.getElementById('statRecords').textContent = '50';
    document.getElementById('statRecordsLabel').textContent = 'STARTUPS';
    document.getElementById('statFeatures').textContent = '5';
    document.getElementById('statFeaturesLabel').textContent = 'PREDICTORS (ML READY)';
    document.getElementById('statExperiments').textContent = '155';
    document.getElementById('badgeTarget').textContent = 'Target: Profit ($)';
    document.getElementById('chartRmseUnit').textContent = '單位: 美元 ($)';
    document.getElementById('simTitle').textContent = '新創公司獲利即時預測計算機 (Live Profit Simulator)';
    document.getElementById('simDesc').textContent = '調動下方新創公司的投入經費與地區，即時以目前選定的多元線性迴歸模型推估淨獲利 (Profit)：';
    document.getElementById('simResultLabel').textContent = 'ESTIMATED PROFIT (推估淨利)';
    document.getElementById('thRmse').textContent = 'Test RMSE ($)';
    document.getElementById('thMae').textContent = 'Test MAE ($)';
  } else {
    document.getElementById('heroBadgeTag').textContent = 'WHO Global Health Observatory • HW2';
    document.getElementById('heroTitlePrefix').textContent = 'WHO Life Expectancy';
    document.getElementById('heroTitleSuffix').textContent = 'Regression Explorer';
    document.getElementById('heroSubtitle').textContent = '以 WHO 全球 193 國健康與經濟指標，探索成人死亡率、教育年數、BMI、GDP等 8 項特徵對平均壽命之影響，並即時預測壽命。';
    document.getElementById('statRecords').textContent = '2,928';
    document.getElementById('statRecordsLabel').textContent = 'COUNTRY RECORDS (193國)';
    document.getElementById('statFeatures').textContent = '8';
    document.getElementById('statFeaturesLabel').textContent = 'HEALTH PREDICTORS';
    document.getElementById('statExperiments').textContent = '255';
    document.getElementById('badgeTarget').textContent = 'Target: Life Expectancy (歲/Years)';
    document.getElementById('chartRmseUnit').textContent = '單位: 歲 (Years)';
    document.getElementById('simTitle').textContent = '國家平均壽命即時推估計算機 (Life Expectancy Simulator)';
    document.getElementById('simDesc').textContent = '調動下方教育、成人死亡率、BMI、GDP、疫苗接種率等數值，即時推估預期壽命 (歲)：';
    document.getElementById('simResultLabel').textContent = 'ESTIMATED LIFE EXPECTANCY (推估壽命)';
    document.getElementById('thRmse').textContent = 'Test RMSE (歲)';
    document.getElementById('thMae').textContent = 'Test MAE (歲)';
  }

  // 2. Render K Buttons
  renderKButtons();

  // 3. Render Simulator Inputs
  renderSimulatorInputs();

  // 4. Render Raw Data Table Structure
  renderRawDataTableStructure();

  // 5. Render Model Update
  renderModelUpdate();
}

function renderKButtons() {
  const container = document.getElementById('kControlGroup');
  container.innerHTML = '';
  const maxK = (appState.dataset === 'startups') ? 5 : 8;

  for (let i = 1; i <= maxK; i++) {
    const btn = document.createElement('button');
    btn.className = 'seg-btn' + (i === appState.k ? ' active' : '');
    btn.dataset.k = i;
    btn.textContent = i;
    btn.addEventListener('click', () => {
      document.querySelectorAll('#kControlGroup .seg-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      appState.k = i;
      renderModelUpdate();
    });
    container.appendChild(btn);
  }
}

function getDatasetData() {
  return ALL_DATA[appState.dataset];
}

function getCurrentModelSeries() {
  const ds = getDatasetData();
  const modeData = ds[appState.mode] || ds['stepwise'];
  return modeData[appState.method] || modeData['Linear Regression'];
}

function getCurrentModel() {
  const series = getCurrentModelSeries();
  return series.find(item => item.k === appState.k) || series[0];
}

function renderModelUpdate() {
  const model = getCurrentModel();
  const series = getCurrentModelSeries();
  const isStartups = (appState.dataset === 'startups');

  // Update Section Title
  document.getElementById('chartSectionTitle').textContent = `${appState.method} - Feature Count Performance`;

  // Update KPI Cards
  if (isStartups) {
    document.getElementById('valRmse').textContent = formatCurrency(model.rmse);
    document.getElementById('descRmse').textContent = 'Root Mean Squared Error (越低越佳)';
    document.getElementById('valR2').textContent = model.r2.toFixed(4);
    document.getElementById('valMae').textContent = formatCurrency(model.mae);
    document.getElementById('descMae').textContent = '平均絕對誤差 (實際金額落差)';
    document.getElementById('valCvRmse').textContent = formatCurrency(model.cv_rmse);
  } else {
    document.getElementById('valRmse').textContent = model.rmse.toFixed(3) + ' 歲';
    document.getElementById('descRmse').textContent = '測試集預測壽命誤差 (均方根誤差)';
    document.getElementById('valR2').textContent = model.r2.toFixed(4);
    document.getElementById('valMae').textContent = model.mae.toFixed(3) + ' 歲';
    document.getElementById('descMae').textContent = '平均絕對誤差 (平均落差年數)';
    document.getElementById('valCvRmse').textContent = model.cv_rmse.toFixed(3) + ' 歲';
  }

  // Trend Highlights
  const isBestK = isStartups ? (model.k === 2 && appState.mode === 'stepwise') : (model.k === 7);
  const trendRmse = document.getElementById('trendRmse');
  const trendR2 = document.getElementById('trendR2');
  if (isBestK) {
    trendRmse.textContent = isStartups ? '⭐ 測試集最佳 RMSE ($8,198.80)' : '⭐ 5-Fold CV 泛化誤差最低';
    trendRmse.className = 'metric-trend positive';
    trendR2.textContent = isStartups ? '⭐ 最佳模型解釋力 (94.74%)' : '⭐ 達到 76.3% 變異解釋力';
    trendR2.className = 'metric-trend positive';
  } else {
    trendRmse.textContent = `第 ${model.k} 階特徵誤差`;
    trendRmse.className = 'metric-trend neutral';
    trendR2.textContent = `判定係數 ${(model.r2 * 100).toFixed(2)}%`;
    trendR2.className = 'metric-trend neutral';
  }

  // Update Predictors Tags
  renderPredictorTags(model);

  // Update Charts
  updateCharts(series);

  // Update Prediction Calculation
  calculatePrediction();

  // Update Summary Table
  renderSummaryTable(series);
}

function renderPredictorTags(model) {
  const container = document.getElementById('predictorTags');
  container.innerHTML = '';
  document.getElementById('predictorCountBadge').textContent = `${model.features.length} Features Selected`;

  const displayList = model.display_features || model.features;
  displayList.forEach((feat, idx) => {
    const tag = document.createElement('div');
    tag.className = 'predictor-tag';
    
    const actualFeat = model.features[idx] || feat;
    const coef = model.coefs[actualFeat];
    const coefText = (coef !== undefined) ? `(β: ${coef >= 0 ? '+' : ''}${coef.toFixed(3)})` : '';

    tag.innerHTML = `
      <span class="tag-dot"></span>
      <span>${feat}</span>
      <span class="tag-coef">${coefText}</span>
    `;
    container.appendChild(tag);
  });
}

function initCharts() {
  const ctxRmse = document.getElementById('rmseChart').getContext('2d');
  const ctxR2 = document.getElementById('r2Chart').getContext('2d');

  const baseConfig = {
    type: 'line',
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: { display: false },
        tooltip: {
          backgroundColor: '#0f172a',
          titleFont: { family: 'Inter', size: 13, weight: 'bold' },
          bodyFont: { family: 'JetBrains Mono', size: 12 },
          padding: 10,
          cornerRadius: 8
        }
      },
      scales: {
        x: {
          title: { display: true, text: 'Number of Features', font: { family: 'Inter', size: 11 } },
          grid: { display: false }
        },
        y: {
          grid: { color: '#f1f5f9' },
          ticks: { font: { family: 'JetBrains Mono', size: 11 } }
        }
      }
    }
  };

  rmseChart = new Chart(ctxRmse, {
    ...baseConfig,
    data: {
      labels: [],
      datasets: [{
        label: 'RMSE',
        data: [],
        borderColor: '#3b75af',
        backgroundColor: '#3b75af',
        pointBackgroundColor: [],
        pointRadius: [],
        borderWidth: 2,
        tension: 0.1
      }]
    }
  });

  r2Chart = new Chart(ctxR2, {
    ...baseConfig,
    data: {
      labels: [],
      datasets: [{
        label: 'R-squared',
        data: [],
        borderColor: '#3b75af',
        backgroundColor: '#3b75af',
        pointBackgroundColor: [],
        pointRadius: [],
        borderWidth: 2,
        tension: 0.1
      }]
    }
  });
}

function updateCharts(series) {
  const kLabels = series.map(item => item.k);
  const rmseValues = series.map(item => item.rmse);
  const r2Values = series.map(item => item.r2);

  const activeIndex = appState.k - 1;

  const pointBgColors = kLabels.map((_, i) => i === activeIndex ? '#ef4444' : '#3b75af');
  const pointRadii = kLabels.map((_, i) => i === activeIndex ? 8 : 4);

  // Update RMSE Chart
  rmseChart.data.labels = kLabels;
  rmseChart.data.datasets[0].data = rmseValues;
  rmseChart.data.datasets[0].pointBackgroundColor = pointBgColors;
  rmseChart.data.datasets[0].pointRadius = pointRadii;
  rmseChart.update();

  // Update R2 Chart
  r2Chart.data.labels = kLabels;
  r2Chart.data.datasets[0].data = r2Values;
  r2Chart.data.datasets[0].pointBackgroundColor = pointBgColors;
  r2Chart.data.datasets[0].pointRadius = pointRadii;
  r2Chart.update();
}

