function calculatePrediction() {
  const model = getCurrentModel();
  let predicted = model.intercept || 0;
  const coefs = model.coefs;
  const isStartups = (appState.dataset === 'startups');

  let formulaParts = [];

  if (isStartups) {
    formulaParts.push(formatCurrency(model.intercept).replace('$', ''));
    if ('R&D Spend' in coefs) {
      predicted += coefs['R&D Spend'] * appState.startups.rdSpend;
      formulaParts.push(`${coefs['R&D Spend'] >= 0 ? '+' : '-'} ${Math.abs(coefs['R&D Spend']).toFixed(3)} × R&D`);
    }
    if ('Administration' in coefs) {
      predicted += coefs['Administration'] * appState.startups.adminSpend;
      formulaParts.push(`${coefs['Administration'] >= 0 ? '+' : '-'} ${Math.abs(coefs['Administration']).toFixed(3)} × Admin`);
    }
    if ('Marketing Spend' in coefs) {
      predicted += coefs['Marketing Spend'] * appState.startups.mktSpend;
      formulaParts.push(`${coefs['Marketing Spend'] >= 0 ? '+' : '-'} ${Math.abs(coefs['Marketing Spend']).toFixed(3)} × Mkt`);
    }
    if ('State_Florida' in coefs && appState.startups.state === 'Florida') {
      predicted += coefs['State_Florida'];
      formulaParts.push(`+ ${coefs['State_Florida'].toFixed(1)} (FL)`);
    }
    if ('State_New York' in coefs && appState.startups.state === 'New York') {
      predicted += coefs['State_New York'];
      formulaParts.push(`+ ${coefs['State_New York'].toFixed(1)} (NY)`);
    }

    document.getElementById('predOutputValue').textContent = formatCurrency(predicted);
    document.getElementById('predFormulaText').textContent = 'Profit = ' + formulaParts.join(' ');
  } else {
    formulaParts.push(model.intercept.toFixed(2));
    Object.keys(coefs).forEach(feat => {
      const c = coefs[feat];
      const val = appState.who[feat] || 0;
      predicted += c * val;
      formulaParts.push(`${c >= 0 ? '+' : '-'} ${Math.abs(c).toFixed(3)} × ${feat.split(' ')[0]}`);
    });

    // Bound prediction realistically
    predicted = Math.max(30, Math.min(95, predicted));

    document.getElementById('predOutputValue').textContent = predicted.toFixed(1) + ' 歲 (Years)';
    document.getElementById('predFormulaText').textContent = 'Life Expectancy = ' + formulaParts.join(' ');
  }
}

function renderSummaryTable(series) {
  const tbody = document.getElementById('summaryTableBody');
  tbody.innerHTML = '';
  const isStartups = (appState.dataset === 'startups');

  series.forEach(item => {
    const tr = document.createElement('tr');
    if (item.k === appState.k) {
      tr.className = 'row-active';
    }

    const isBest = isStartups ? (appState.mode === 'stepwise' && item.k === 2) : (item.k === 7);
    const statusHtml = isBest
      ? '<span class="status-badge best">⭐ 最優模型</span>'
      : '<span class="status-badge normal">有效評估</span>';

    const featNames = (item.display_features || item.features).join(', ');
    const rmseText = isStartups ? formatCurrency(item.rmse) : item.rmse.toFixed(4);
    const maeText = isStartups ? formatCurrency(item.mae) : item.mae.toFixed(4);

    tr.innerHTML = `
      <td><strong>${item.k}</strong></td>
      <td><code>[${featNames}]</code></td>
      <td style="font-family: var(--font-mono);">${rmseText}</td>
      <td style="font-family: var(--font-mono); font-weight: 600;">${item.r2.toFixed(6)}</td>
      <td style="font-family: var(--font-mono);">${maeText}</td>
      <td>${statusHtml}</td>
    `;
    tbody.appendChild(tr);
  });
}

