function filterRawDataTable(keyword) {
  const ds = getDatasetData();
  if (!keyword.trim()) {
    renderRawDataTable(ds.raw_records);
    return;
  }
  const isStartups = (appState.dataset === 'startups');
  const filtered = ds.raw_records.filter(r => {
    if (isStartups) {
      return r.State.toLowerCase().includes(keyword) ||
             String(r['R&D Spend']).includes(keyword) ||
             String(r['Profit']).includes(keyword);
    } else {
      return r.Country.toLowerCase().includes(keyword) ||
             String(r.Year).includes(keyword) ||
             String(r['Life expectancy']).includes(keyword);
    }
  });
  renderRawDataTable(filtered);
}

function formatCurrency(val) {
  return '$' + Number(val).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}
